export function fibRecursive(n: number): number {
  if (n < 2) {
    return n;
  }

  let previous = 0;
  let current = 1;
  for (let i = 2; i <= n; i++) {
    const next = previous + current;
    previous = current;
    current = next;
  }
  return current;
}

